            let mut p_minus_1_bits: [bool; 254] = modulus_be_bits().as_array();
            assert(p_minus_1_bits[254 - 1]);
            p_minus_1_bits[254 - 1] = false;

            let p_minus_1 = from_be_bits::<254>(p_minus_1_bits);
