pub unconstrained fn set_contract_sync_cache_invalid<let N: u32>(
    contract_address: AztecAddress,
    scopes: BoundedVec<AztecAddress, N>,
) {
    set_contract_sync_cache_invalid_oracle(contract_address, scopes);
}

