    let unique_siloed_note_hash_from_nonce = compute_unique_note_hash(nonce, siloed_note_hash);
    let unique_siloed_note_hash = compute_note_nonce_and_unique_note_hash(
        siloed_note_hash,
        first_nullifier,
        note_index_in_tx,
